args.command:
cat > ~/dose.py <<'EOF'
import sys, workcell, re
tare=float(sys.argv[1]); target=tare+250.0
def rd():
    r=workcell.call("scale","read"); return float(re.search(r"([-\d.]+) g",r.text).group(1))
w=rd()
while True:
    rem=target-w
    if rem< -0.15:
        workcell.call("robot","remove")
    elif rem>65: workcell.call("robot","dose","bulk")
    elif rem>14: workcell.call("robot","dose","coarse")
    elif rem>2: workcell.call("robot","dose","fine")
    elif rem>0.06: workcell.call("robot","dose","micro")
    else: break
    w=rd(); print(round(w-tare,2), flush=True)
print(workcell.call("robot","status").text)
EOF
python3 ~/dose.py 119.57

